class UsernameSerializer(serializers.Serializer):
    username = serializers.CharField()

    def validate_username(self, value):
        if value.lower() == "admin":
            raise serializers.ValidationError("That name is reserved.")
        return value.lower()

s = UsernameSerializer(data={"username": " ADMIN "})
print(s.is_valid(), s.errors["username"][0])   # False That name is reserved.
s = UsernameSerializer(data={"username": " Grace "})
print(s.is_valid(), s.validated_data)          # True {'username': 'grace'}

class TripSerializer(serializers.Serializer):
    start = serializers.IntegerField()
    end = serializers.IntegerField()

    def validate(self, attrs):
        if attrs["end"] < attrs["start"]:
            raise serializers.ValidationError(
                {"end": "The trip can't end before it starts."})
        return attrs

s = TripSerializer(data={"start": 10, "end": 4})
print(s.is_valid())        # False
print(s.errors["end"][0])  # The trip can't end before it starts.

